var n=`1012-nam-tok-moo`;var t=`world-1012`;var s=`TH`;var o=`southeast-asia`;var a=4;var r=66;var l={en:`Nam Tok Moo`,ua:`Нам ток му`};var u={en:`Nam Tok Moo is a dish from Thailand prepared with pork shoulder, fish sauce, lime juice, shallot. This is a home-scale version with measured ingredients in the individual steps where they are used. Pork shoulder replaces customary pork neck in nam tok moo.`,ua:`Нам ток му, страва кухні країни Таїланд, яку готують із таких продуктів: свиняча лопатка, рибний соус, сік лайма, цибуля шалот. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Свиняча лопатка замінює традиційний ошийок у нам ток му.`};var g=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 35 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 35 хвилин.`,t:[`marinating`],m:35,i:[[`pork-shoulder`,650,`g`],[`fish-sauce`,35,`ml`],[`white-granulated-sugar`,15,`g`],[`ground-black-pepper`,3,`g`]]},{en:`Grill the marinated portions from the preceding steps, turning to cook evenly and checking the safe internal temperature.`,ua:`Готуйте замариновані порції на грилі, перевертаючи для рівномірного нагрівання та перевіряючи безпечну температуру всередині.`,t:[`grilling`],m:18,i:[]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`lime-juice`,50,`ml`],[`shallot`,80,`g`],[`bird-s-eye-chili`,2,`pcs`],[`fish-sauce`,18,`ml`]]},{en:`Toast these ingredients over medium heat for about 5 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 5 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:5,i:[[`glutinous-rice`,25,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`mint`,20,`g`],[`cilantro`,20,`g`],[`lettuce`,180,`g`]]}];var m={slug:n,id:t,country:`TH`,region:o,servings:4,minutes:66,title:l,text:u,steps:g};export{s as country,m as default,t as id,r as minutes,o as region,a as servings,n as slug,g as steps,u as text,l as title};